import os


def create_commands_list(dir_path):
    """

    :param dir_path:
    :return:
    """
    cmds = ['\t- {}'.format(cmd.replace('.py', '')) for cmd in os.listdir(dir_path) if cmd != '__init__.py']
    print('\n'.join(cmds))
    return '\n'.join(cmds)
